import{_ as a,o as e,c as d,ai as o}from"./chunks/framework.scx6l_IK.js";const b=JSON.parse('{"title":"孝","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-孝.md","filePath":"50-概念资料/dict-孝.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-孝.md"};function l(i,t,h,c,n,u){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="孝" tabindex="-1">孝 <a class="header-anchor" href="#孝" aria-label="Permalink to &quot;孝&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：报恩 | 道家对应：归根</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;孝&quot;就是<strong>对父母的感恩和回报</strong>。了空居士不讲&quot;孝&quot;的繁复规矩，而是从因果和感恩两个角度切入：父母是生命的源头——不孝的人，因果上割裂了自己的根。</p><p>他说&quot;儿孙自有儿孙福，莫为儿孙做马牛&quot;——这既是对父母的提醒（不要过度干涉子女），也是孝的另一面：子女不要让父母操心。孝的最高境界不是供养，是让父母安心。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;儿孙自有儿孙福，莫为儿孙做马牛。不是不管，是不要过度干涉。你把你的人生经验告诉他们，选择让他们自己做。&quot; — 处世系列</p></blockquote><blockquote><p>&quot;天地间有位才女李清照，她病重时对丈夫写&#39;莫对新人提旧妇&#39;，对儿子写&#39;须教继母作亲娘&#39;。&quot; — 修行入世（20090112b）</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>孝就是听父母的话</td><td>孝是感恩和关爱，不是盲从。父母有错，温和地指出也是孝</td></tr><tr><td>修行了就不需要管父母了</td><td>父母是最近的众生，对父母的照顾就是对众生的照顾</td></tr><tr><td>孝就是给父母钱</td><td>孝最重要的是让父母安心——你的生活稳定、做人正直是最大的孝</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>侧重</th></tr></thead><tbody><tr><td>儒家</td><td>孝</td><td>人伦之本，百善孝为先</td></tr><tr><td>佛家</td><td>报恩</td><td>上报四重恩（父母恩第一）</td></tr><tr><td>道家</td><td>归根</td><td>回归生命本源</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-家庭道场">dict-家庭道场</a> — 行孝是家庭道场的核心修行</li><li><a href="/50-概念资料/dict-仁">dict-仁</a> — 孝是仁的最初表现——爱人从爱父母开始</li><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 对父母的恭敬是敬的根基</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-历境炼心">model-历境炼心</a> — 对父母的态度是检验修行功夫的标尺</li><li><a href="/10-核心模型/model-天人合一">model-天人合一</a> — 父母是生命场的源头，不孝则割裂因果场</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>每周至少和父母通话一次——不是敷衍的问候，是让他们知道你过得怎么样、你在做什么。不让父母为你操心，就是最基础的孝。</p>',18)])])}const q=a(r,[["render",l]]);export{b as __pageData,q as default};
